def build(root=ROOT):
    root=Path(root)
    for rel in SOURCE_FILES:
        text=(root/rel).read_text(encoding='utf-8')
        ast.parse(text) if rel.endswith('.py') else json.loads(text)
    runtime=(root/'runtime/wan'/f'{STEM}.py').read_text()
    helpers='\n\n'.join(ast.get_source_segment(runtime,n) for n in ast.parse(runtime).body
        if (isinstance(n,ast.FunctionDef) and n.name in ('execution_artifacts','recover_ledger','plan_units','denominators','tasks','task_id','quality_specs')) or
           (isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id in ('SOURCES','ARMS','KEYS','WINDOWS','FIXTURES') for t in n.targets)))
    bootstrap=BOOTSTRAP.replace('{RECOVERY_HELPERS}',helpers)
    codes=["from google.colab import drive\ndrive.mount('/content/drive')\n",bootstrap,RUN,DISPLAY]
    notes=[
        '# RANK3：四新源阶段2确认\n\n直接 Run all。默认下载公开 B 分支 dev/local-joint-state-payload-v1 可用源码到隔离目录；无需源码 ZIP。第一代码单元仅挂载 Drive。',
        '## 输入与只读恢复\n\n旧输入 fixed-four-new-v1 仅提供已冻结背景和 τ=0.49221603782894896。四新源的 prompt、seed、a 和 eval 角色固定。新输出 B-Rank3-Four-Source-Confirmation-V1/fixed-four-new-v1；已有 attempt 时在下载与 setup 前只读恢复，不续跑或补缺。',
        '## 一次固定预算\n\nγ=1；8 trajectories / 400 steps / 800 DiT / 100 local gradients / 4 state；D181=12、E41=432、codec encode/probe/decode各48。无新校准、搜索或 bundles。五读法共享观测：72 tasks，每读法 384 positive + 1920 null 槽。全部 plans 回读后才消费缓存位，全部 blind decisions 回读后才做真值评价。首技术失败停止并保留未进入项。',
        '## 方法判断与证据上限\n\nRANK3 至少288实际支持正确槽、每源至少48、至少9阳性DETECT且每源至少2；不得丢失CDC_M实际支持正确槽，错误/误归因/无实际支持输出/null DETECT均为零。全部方法判据满足后，净增至少32槽才宣称固定范围新增贡献。76份直接质量比较只报告数值，不设未采纳质量阈值。null DETECT立即记录候选失败，仅完成既定保存数据诊断。']
    cells=[]
    for i,(note,code) in enumerate(zip(notes,codes),1):
        ast.parse(code)
        cells.extend([dict(cell_type='markdown',id=f'rank3-note-{i}',metadata={},source=(note+'\n').splitlines(keepends=True)),
            dict(cell_type='code',id=f'rank3-code-{i}',metadata={},source=code.splitlines(keepends=True),execution_count=None,outputs=[])])
    notebook=dict(cells=cells,metadata=dict(kernelspec=dict(display_name='Python 3',language='python',name='python3')),nbformat=4,nbformat_minor=5)
    dest=root/'notebooks'/(STEM+'.ipynb');dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(json.dumps(notebook,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
    return dict(notebook=str(dest),delivery='CONFIGURED_B_BRANCH_SOURCE',source_ref='dev/local-joint-state-payload-v1',code_cells=4,source_files=list(SOURCE_FILES))

if __name__=='__main__':print(json.dumps(build(),ensure_ascii=False,indent=2))
